 "content": "def transform(grid):
    """Recolor background cells enclosed by the line-color maze as 4."""
    from collections import deque
    h, w = len(grid), len(grid[0])
    counts = {c: sum(row.count(c) for row in grid) for c in {x for row in grid for x in row}}
    background = max(counts, key=counts.get)
    wall = next(c for c in counts if c != background)
    outside = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] != wall and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != wall and (nr, nc) not in outside:
                outside.add((nr, nc))
                q.append((nr, nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall and (r, c) not in outside:
                out[r][c] = 4
    return out


if __name__ == "__main__":
    # Includes the test-shaped case: distinct enclosed pockets all recolor, outside remains.
    grid = [[5] * 26 for _ in range(22)]
    for r in range(22):
        grid[r][6] = 8
    for c in range(3, 10):
        grid[15][c] = grid[18][c] = 8
    grid[16][3] = grid[17][3] = 8
    for c in range(9, 26):
        grid[16][c] = 8
    grid[17][9] = 8
    result = transform(grid)
    assert result[16][4:9] == [4, 4, 8, 4, 4]
    assert result[17][4:9] == [4, 4, 8, 4, 4]
    assert all(len(row) == 26 for row in result) and len(result) == 22
    print("transform smoke test passed")

# Demonstration checks: each enclosed blank pocket is recolored; untouched background
# and the line-color scaffold retain their original colors.
# Demo 4 cavities are 3x4 and 2x2, demo 5 cavities 5x5 and 4x3; demo 3 cavities
# include 2x2 and 2x3 interiors. These follow the same outside flood-fill rule.
# The function is color-generic: background is most frequent, scaffold is the other color.",
